input.valid { border-color: #27ae60; }
.error-msg { color: #c0392b; font-size: 0.78rem; margin-top: 0.2rem; min-height: 1em; }
.password-wrap { position: relative; }
.password-wrap input { padding-right: 2.5rem; }
.toggle-pw { position: absolute; right: 0.4rem; top: 50%; transform: translateY(-50%); background: none; border: none; cursor: pointer; font-size: 0.8rem; color: #e67e22; padding: 0.2rem 0.4rem; border-radius: 3px; }
.toggle-pw:hover { background: rgba(230,126,34,0.1); }
.checkbox-field { display: flex; align-items: flex-start; gap: 0.5rem; margin-top: 0.5rem; }
.checkbox-field input[type="checkbox"] { margin-top: 0.2rem; width: 1rem; height: 1rem; accent-color: #e67e22; }
.checkbox-field label { font-size: 0.85rem; font-weight: 400; color: #34495e; }
.actions { margin-top: 1.25rem; display: flex; justify-content: flex-end; }
