<body>
<header><h1>Service Registration</h1></header>
<main>
<div class="panel">
<h2>Create Your Account</h2>
<div id="successBanner" class="success-banner" role="status" aria-live="polite"></div>
<form id="regForm" novalidate>
<div class="form-grid">
<div class="field">
<label for="username">Username <span aria-hidden="true">*</span></label>
<input type="text" id="username" name="username" required autocomplete="username" minlength="3" maxlength="30" placeholder="Choose a username">
<div class="error-msg" id="usernameError" aria-live="polite"></div>
</div>
<div class="field">
<label for="email">Email Address <span aria-hidden="true">*</span></label>
<input type="email" id="email" name="email" required autocomplete="email" placeholder="you@example.com">
<div class="error-msg" id="emailError" aria-live="polite"></div>
</div>
<div class="field">
<label for="dob">Date of Birth</label>
<input type="date" id="dob" name="dob" autocomplete="bday">
<div class="error-msg" id="dobError" aria-live="polite"></div>
</div>
<div class="field">
<label for="password">Password <span aria-hidden="true">*</span></label>
<div class="password-wrap">
<input type="password" id="password" name="password" required autocomplete="new-password" minlength="8" placeholder="Min 8 characters">
<button type="button" class="toggle-pw" data-target="password" aria-label="Show password">Show</button>
</div>
<div class="error-msg" id="passwordError" aria-live="polite"></div>
</div>
<div class="field full">
<label for="confirmPassword">Confirm Password <span aria-hidden="true">*</span></label>
<div class="password-wrap">
<input type="password" id="confirmPassword" name="confirmPassword" required autocomplete="new-password" placeholder="Re-enter password">
<button type="button" class="toggle-pw" data-target="confirmPassword" aria-label="Show confirm password">Show</button>
</div>
<div class="error-msg" id="confirmPasswordError" aria-live="polite"></div>
</div>
<div class="field full checkbox-field">
<input type="checkbox" id="terms" name="terms" required>
<label for="terms">I accept the <a href="#" onclick="return false;">Terms of Service</a> <span aria-hidden="true">*</span></label>
</div>
</div>
<div class="actions">
<button type="submit" class="btn-submit">Register</button>
</div>
</form>
</div>
</main>
<script>
(function(){
  const form = document.getElementById('regForm');
  const successBanner = document.getElementById('successBanner');
  const fields = {
    username: document.getElementById('username'),
    email: document.getElementById('email'),
    dob: document.getElementById('dob'),
    password: document.getElementById('password'),
    confirmPassword: document.getElementById('confirmPassword'),
    terms: document.getElementById('terms')
  };
  const errors = {
    username: document.getElementById('usernameError'),
    email: document.getElementById('emailError'),
    dob: document.getElementById('dobError'),
    password: document.getElementById('passwordError'),
    confirmPassword: document.getElementById('confirmPasswordError')
  };

  // Toggle password visibility
  document.querySelectorAll('.toggle-pw').forEach(btn => {
    btn.addEventListener('click', () => {
      const target = document.getElementById(btn.dataset.target);
      if (target.type === 'password') {
        target.type = 'text';
        btn.textContent = 'Hide';
        btn.setAttribute('aria-label', 'Hide password');
      } else {
        target.type = 'password';
        btn.textContent = 'Show';
        btn.setAttribute('aria-label', 'Show password');
      }
      target.focus();
    });
  });

  function setError(fieldId, msg) {
    errors[fieldId].textContent = msg;
    fields[fieldId].classList.add('invalid');
    fields[fieldId].classList.remove('valid');
  }
  function clearError(fieldId) {
    errors[fieldId].textContent = '';
    fields[fieldId].classList.remove('invalid');
  }
  function setValid(fieldId) {
    clearError(fieldId);
    fields[fieldId].classList.add('valid');
  }

  function validateUsername() {
    const v = fields.username.value.trim();
    if (!v) { setError('username', 'Username is required.'); return false; }
    if (v.length < 3) { setError('username', 'Username must be at least 3 characters.'); return false; }
    if (v.length > 30) { setError('username', 'Username must be at most 30 characters.'); return false; }
    if (!/^[a-zA-Z0-9_]+$/.test(v)) { setError('username', 'Use only letters, numbers, and underscores.'); return false; }
    // Check duplicate
    const registered = JSON.parse(localStorage.getItem('registeredUsers') || '[]');
    if (registered.some(u => u.username.toLowerCase() === v.toLowerCase())) {
      setError('username', 'This username is already taken.'); return false;
    }
    setValid('username'); return true;
  }

  function validateEmail() {
    const v = fields.email.value.trim();
    if (!v) { setError('email', 'Email is required.'); return false; }
    const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRe.test(v)) { setError('email', 'Enter a valid email address.'); return false; }
    const registered = JSON.parse(localStorage.getItem('registeredUsers') || '[]');
    if (registered.some(u => u.email.toLowerCase() === v.toLowerCase())) {
      setError('email', 'This email is already registered.'); return false;
    }
    setValid('email'); return true;
  }

  function validateDob() {
    const v = fields.dob.value;
    if (!v) { clearError('dob'); fields.dob.classList.remove('valid','invalid'); return true; }
    const d = new Date(v);
    if (isNaN(d.getTime())) { setError('dob', 'Enter a valid date.'); return false; }
    const today = new Date();
    const age = (today - d) / (365.25*24*60*60*1000);
    if (age < 13) { setError('dob', 'You must be at least 13 years old.'); return false; }
    if (age > 120) { setError('dob', 'Enter a realistic date of birth.'); return false; }
    setValid('dob'); return true;
  }

  function validatePassword() {
    const v = fields.password.value;
    if (!v) { setError('password', 'Password is required.'); return false; }
    if (v.length < 8) { setError('password', 'Password must be at least 8 characters.'); return false; }
    setValid('password'); return true;
  }

  function validateConfirmPassword() {
    const v = fields.confirmPassword.value;
    if (!v) { setError('confirmPassword', 'Please confirm your password.'); return false; }
    if (v !== fields.password.value) { setError('confirmPassword', 'Passwords do not match.'); return false; }
    setValid('confirmPassword'); return true;
  }

  function validateTerms() {
    if (!fields.terms.checked) { return false; }
    return true;
  }

  // Real-time validation on blur
  fields.username.addEventListener('blur', validateUsername);
  fields.email.addEventListener('blur', validateEmail);
  fields.dob.addEventListener('blur', validateDob);
  fields.password.addEventListener('blur', validatePassword);
  fields.confirmPassword.addEventListener('blur', validateConfirmPassword);

  // Clear validity styling on input to reduce noise
  Object.keys(fields).forEach(key => {
    if (key === 'terms') return;
    fields[key].addEventListener('input', () => {
      if (fields[key].classList.contains('invalid')) {
        // re-validate on input if already invalid
        if (key === 'username') validateUsername();
        else if (key === 'email') validateEmail();
        else if (key === 'dob') validateDob();
        else if (key === 'password') { validatePassword(); validateConfirmPassword(); }
        else if (key === 'confirmPassword') validateConfirmPassword();
      }
    });
  });

  form.addEventListener('submit', function(e) {
    e.preventDefault();
    successBanner.classList.remove('visible');
    successBanner.textContent = '';

    const r1 = validateUsername();
    const r2 = validateEmail();
    const r3 = validateDob();
    const r4 = validatePassword();
    const r5 = validateConfirmPassword();
    const r6 = validateTerms();

    if (!r6) {
      // Focus terms checkbox area
      fields.terms.focus();
    }

    if (r1 && r2 && r3 && r4 && r5 && r6) {
      const userData = {
        username: fields.username.value.trim(),
        email: fields.email.value.trim(),
        dob: fields.dob.value || null,
        registeredAt: new Date().toISOString()
      };
      const registered = JSON.parse(localStorage.getItem('registeredUsers') || '[]');
      registered.push(userData);
      localStorage.setItem('registeredUsers', JSON.stringify(registered));

      successBanner.textContent = 'Registration successful! Welcome, ' + userData.username + '.';
      successBanner.classList.add('visible');
      form.reset();
      // Clear validity classes
      Object.keys(fields).forEach(key => {
        if (key === 'terms') return;
        fields[key].classList.remove('valid', 'invalid');
      });
      Object.keys(errors).forEach(key => { errors[key].textContent = ''; });
      fields.username.focus();
    }
  });
})();
</script>
</body>
